// Lấy output từ AI Agent
const raw = $input.first().json.output;

// Tự động parse JSON dù AI trả về chuỗi hay object
let data;
try {
  const clean = String(raw).replace(/```json/g, '').replace(/```/g, '').trim();
  data = typeof raw === 'string' ? JSON.parse(clean) : raw;
} catch (e) {
  throw new Error('AI khong tra ve JSON hop le. Output thuc te: ' + raw);
}

// Lấy số dòng từ Google Sheet
const rowNumber = $('get imformation post').first().json.row_number;

// Tách thành 4 item riêng để loop và sửa qua Telegram
return [
  { json: { field: 'subject',    value: data.subject,    rowNumber } },
  { json: { field: 'paragraph1', value: data.paragraph1, rowNumber } },
  { json: { field: 'paragraph2', value: data.paragraph2, rowNumber } },
  { json: { field: 'paragraph3', value: data.paragraph3, rowNumber } },
];

